{-# OPTIONS_GHC -Wall #-}
{-# LANGUAGE PatternGuards #-}
-- Ficcus (SIZED, G24 and G41; docs/SIZED-PLAN.md): the sized integers `Int8 Int16 Int32 Word8 Word16 Word32 Word64` and `Float32`.
--
-- A sized type is declared in its overlay module (overlay/Int8.elm ... , generated by ficcus-tools/gen_sized.py) as a type with one
-- constructor, the marker, that is never built, and with the well known members of AST.WellKnown, so the type checker accepts the
-- operators at it like at any custom type with members (A3).  Here is what the specializer and the C generator need: which types they
-- are (only when the union has the marker: a module `Int8` of the project is ordinary code), the class of a value (the 8 byte slot of
-- Int or Float), the kernel id of each operation, its C text, the range of a literal and the pieces for the structural code.
-- `Int64` and `Float64` are type aliases of Int and Float and need nothing here.
module Ficcus.Mono.Sized
  ( Sized(..)
  , allSized
  , typeName, typeTag, typeId, markerName, isFloat, isSigned, bitsOf
  , sizedOfTypeId
  , sizedEnabled
  , sizedEnums
  , classOfSized
  , kernelId
  , sizedKernelArity
  , sizedKernelSig
  , parseKernelId
  , moduleFunctionOp
  , operatorOp
  , memberOp
  , kernelC
  , cmpC
  , showC
  , literalValue
  , literalNeedsCall
  , wordWithoutStructuralOrder
  )
  where


import qualified Data.List as List
import qualified Data.Map.Strict as Map

import Ficcus.Mono.Class (Class(..))
import Ficcus.Mono.Ir (UnionShape(..))


data Sized = I8 | I16 | I32 | U8 | U16 | U32 | U64 | F32
  deriving (Eq, Ord, Show, Enum, Bounded)


allSized :: [Sized]
allSized = [minBound .. maxBound]


-- | the name of the type and of its module
typeName :: Sized -> String
typeName s =
  case s of
    I8 -> "Int8"; I16 -> "Int16"; I32 -> "Int32"
    U8 -> "Word8"; U16 -> "Word16"; U32 -> "Word32"; U64 -> "Word64"
    F32 -> "Float32"


-- | the lower case tag of the C functions (`fic_sz_<tag>_add`)
typeTag :: Sized -> String
typeTag s =
  case s of
    I8 -> "i8"; I16 -> "i16"; I32 -> "i32"
    U8 -> "u8"; U16 -> "u16"; U32 -> "u32"; U64 -> "u64"
    F32 -> "f32"


-- | the id of the type as the specializer names it (the module of the overlay is compiled as a module of the project)
typeId :: Sized -> String
typeId s = "author/project:" ++ typeName s ++ "." ++ typeName s


markerName :: Sized -> String
markerName s = "Fic" ++ typeName s ++ "Builtin"


isFloat :: Sized -> Bool
isFloat s = s == F32


isSigned :: Sized -> Bool
isSigned s = s `elem` [I8, I16, I32]


bitsOf :: Sized -> Int
bitsOf s =
  case s of
    I8 -> 8; U8 -> 8; I16 -> 16; U16 -> 16; I32 -> 32; U32 -> 32; U64 -> 64; F32 -> 32


sizedOfTypeId :: String -> Maybe Sized
sizedOfTypeId tid = lookup tid [ (typeId s, s) | s <- allSized ]


-- | the sized type of a type id, when the union is the overlay's (it has the marker as its only constructor)
sizedEnabled :: Map.Map String UnionShape -> String -> Maybe Sized
sizedEnabled unions tid =
  do  s <- sizedOfTypeId tid
      u <- Map.lookup tid unions
      if [ c | (c, _, _) <- usCtors u ] == [markerName s] then Just s else Nothing


-- | pseudo entries for the table of enumerations (`classOfName`): the key `sized:<type id>` says that the type is a sized one
sizedEnums :: Map.Map String UnionShape -> Map.Map String Bool
sizedEnums unions =
  Map.fromList [ ("sized:" ++ typeId s, True) | s <- allSized, Just _ <- [sizedEnabled unions (typeId s)] ]


classOfSized :: Sized -> Class
classOfSized s = if isFloat s then CF64 else CI64



-- KERNELS


kernelId :: Sized -> String -> String
kernelId s op = "elm/core:Sized." ++ typeName s ++ "." ++ op


parseKernelId :: String -> Maybe (Sized, String)
parseKernelId cid =
  do  rest <- List.stripPrefix "elm/core:Sized." cid
      case break (== '.') rest of
        (t, '.' : op) -> do { s <- lookup t [ (typeName x, x) | x <- allSized ]; return (s, op) }
        _ -> Nothing


-- | the operations of a type and their arities
opsOf :: Sized -> [(String, Int)]
opsOf s
  | isFloat s = common ++ [ ("div", 2), ("fromFloat", 1), ("toFloat", 1) ]
  | otherwise =
      common ++ [ ("idiv", 2), ("mod", 2), ("rem", 2), ("and", 2), ("or", 2), ("xor", 2), ("complement", 1)
                , ("shiftLeftBy", 2), ("shiftRightBy", 2), ("popCount", 1) ]
  where
    common =
      [ ("fromInt", 1), ("toInt", 1), ("add", 2), ("sub", 2), ("mul", 2), ("pow", 2), ("neg", 1), ("abs", 1)
      , ("lt", 2), ("le", 2), ("gt", 2), ("ge", 2), ("eq", 2), ("neq", 2), ("compare", 2), ("toString", 1) ]


-- | the table of kernel arities (by id)
sizedKernelArity :: String -> Maybe Int
sizedKernelArity cid =
  do  (s, op) <- parseKernelId cid
      lookup op (opsOf s)


-- | the ownership signature: no argument is a reference
sizedKernelSig :: String -> Maybe String
sizedKernelSig cid = (`replicate` 's') <$> sizedKernelArity cid


-- | the function of the module of the type that is the kernel of the same name (`Int8.toInt`, `Word8.shiftLeftBy`, ...)
moduleFunctionOp :: Sized -> String -> Maybe String
moduleFunctionOp s name =
  if name `elem` ["fromInt", "toInt", "toString", "and", "or", "xor", "complement", "shiftLeftBy", "shiftRightBy", "popCount", "fromFloat", "toFloat"]
     && Just True == fmap (const True) (lookup name (opsOf s))
    then Just name
    else Nothing


-- | the operation that an operator or a function of Basics is at a sized type (by the id the specializer uses)
operatorOp :: String -> Maybe String
operatorOp cid =
  lookup cid
    [ ("elm/core:Basics.add", "add"), ("elm/core:Basics.sub", "sub"), ("elm/core:Basics.mul", "mul"), ("elm/core:Basics.pow", "pow")
    , ("elm/core:Basics.negate", "neg"), ("elm/core:Basics.abs", "abs")
    , ("elm/core:Basics.fdiv", "div"), ("elm/core:Basics.idiv", "idiv")
    , ("elm/core:Basics.modBy", "mod"), ("elm/core:Basics.remainderBy", "rem")
    , ("elm/core:Basics.lt", "lt"), ("elm/core:Basics.gt", "gt"), ("elm/core:Basics.le", "le"), ("elm/core:Basics.ge", "ge")
    , ("elm/core:Basics.compare", "compare"), ("elm/core:Basics.eq", "eq"), ("elm/core:Basics.neq", "neq")
    ]


-- | the operation of a well known member (`add`, ..., `fromInt`; `eq` is the structural one)
memberOp :: String -> Maybe String
memberOp member =
  if member `elem` ["add", "sub", "mul", "pow", "neg", "abs", "fromInt", "compare", "eq", "div", "idiv", "mod", "rem"] then Just member else Nothing


-- | the C text of the call of a kernel (the arguments are atoms); Nothing: not a sized kernel.  Order is LT 0, EQ 1, GT 2.
kernelC :: String -> [String] -> Maybe String
kernelC cid args =
  do  (s, op) <- parseKernelId cid
      let t = typeTag s
          fn n = "fic_sz_" ++ t ++ "_" ++ n
          call n = fn n ++ "(" ++ List.intercalate ", " args ++ ")"
      case (op, args) of
        ("eq", [a, b]) -> Just ("(" ++ a ++ " == " ++ b ++ ")")
        ("neq", [a, b]) -> Just ("(" ++ a ++ " != " ++ b ++ ")")
        ("compare", [a, b]) -> Just ("(" ++ fn "cmp" ++ "(" ++ a ++ ", " ++ b ++ ") + 1)")
        ("complement", _) -> Just (call "not")
        ("shiftLeftBy", _) -> Just (call "shl")
        ("shiftRightBy", _) -> Just (call "shr")
        ("toString", _) -> Just (call "tostr")
        ("pow", [a, b]) | isFloat s -> Just ("FIC_SZ_F32(fic_fd_pow(" ++ a ++ ", " ++ b ++ "))")
        ("lt", [a, b]) | isFloat s -> Just ("fic_f_lt(" ++ a ++ ", " ++ b ++ ")")
        ("le", [a, b]) | isFloat s -> Just ("fic_f_le(" ++ a ++ ", " ++ b ++ ")")
        ("gt", [a, b]) | isFloat s -> Just ("fic_f_gt(" ++ a ++ ", " ++ b ++ ")")
        ("ge", [a, b]) | isFloat s -> Just ("fic_f_ge(" ++ a ++ ", " ++ b ++ ")")
        _ | Just _ <- lookup op (opsOf s) -> Just (call (lower op))
        _ -> Nothing
  where
    lower op = case op of { "fromInt" -> "fromint"; "toInt" -> "toint"; "fromFloat" -> "fromfloat"; "toFloat" -> "tofloat"; "popCount" -> "popcount"; _ -> op }


-- | the sign of the comparison of two values of the type, as an `int` expression (the structural code of lists, tuples, records)
cmpC :: Sized -> String -> String -> String
cmpC s a b = "fic_sz_" ++ typeTag s ++ "_cmp(" ++ a ++ ", " ++ b ++ ")"


-- | the statement that prints a value into the buffer `sb` (a pointer), as `Debug.toString` does
showC :: Sized -> String -> String -> String
showC s sb v = "fic_sz_" ++ typeTag s ++ "_show(" ++ sb ++ ", " ++ v ++ ");"


-- | a type whose structural order (in a list, tuple, record or as a key) is not the order of the type: the value is held as a
-- signed 64 bit integer.  Only Word64 (the others are held sign or zero extended, where the signed order is the order).
wordWithoutStructuralOrder :: Sized -> Bool
wordWithoutStructuralOrder s = s == U64



-- LITERALS


-- | the value of an integer literal at the type as the C constant (an int64: Word64 above 2^63 as the signed bits), or the message
-- when it is out of range.  `negated`: the literal is written `-n`.
literalValue :: Sized -> Bool -> Integer -> Either String Integer
literalValue s negated n
  | isFloat s = Right (if negated then negate n else n)
  | v < lo || v > hi =
      Left ("The literal `" ++ (if negated then "-" else "") ++ show n ++ "` does not fit in a `" ++ typeName s ++ "`, which holds " ++ show lo ++ " to " ++ show hi ++ ".\n"
            ++ (if not (isSigned s) && negated then "A `" ++ typeName s ++ "` cannot be negative; `" ++ typeName s ++ ".fromInt` (which wraps around) makes one from an `Int` when that is what you want."
                else "`" ++ typeName s ++ ".fromInt` takes an `Int` and wraps around (keeps the low " ++ show (bitsOf s) ++ " bits) when that is what you want."))
  | s == U64 && v >= 2 ^ (63 :: Int) = Right (v - 2 ^ (64 :: Int))
  | otherwise = Right v
  where
    v = if negated then negate n else n
    (lo, hi)
      | isSigned s = (negate (2 ^ (bitsOf s - 1)), 2 ^ (bitsOf s - 1) - 1)
      | otherwise = (0, 2 ^ bitsOf s - 1)


-- | a Float32 literal that a double does not hold exactly after rounding to float needs the conversion at run time: only the
-- integers up to 2^24 are exact
literalNeedsCall :: Sized -> Integer -> Bool
literalNeedsCall s n = isFloat s && abs n > 2 ^ (24 :: Int)
